    private static float[][] tosTubes() {
        float[][] t = new float[24][];
        for (int r = 0; r < 4; ++r) {
            for (int c = 0; c < 6; ++c) {
                t[r * 6 + c] = new float[]{(c - 2.5f) * 0.26f, 0.22f + 0.255f * r, 4.75f};
            }
        }
        return t;
    }

    private static float[][] uralSeats() {
        float[][] s = new float[14][];
        s[0] = new float[]{0.5f, 1.48f, 0.95f};
        s[1] = new float[]{-0.5f, 1.48f, 0.95f};
        for (int i = 0; i < 6; ++i) {
            s[2 + 2 * i] = new float[]{0.82f, 1.8f, -0.65f - 0.5f * i};
            s[3 + 2 * i] = new float[]{-0.82f, 1.8f, -0.65f - 0.5f * i};
        }
        return s;
    }

    private static String[] uralRoles() {
        String[] r = new String[14];
        java.util.Arrays.fill(r, "passenger");
        r[0] = "driver";
        return r;
    }

