    private static float[][] yarsWheels() {
        float[] az = {8.35f, 6.55f, 4.15f, 2.35f, -0.55f, -2.35f, -4.75f, -6.55f};
        float[][] w = new float[16][];
        for (int a = 0; a < 8; ++a) {
            w[2 * a] = new float[]{1.38f, 0.8f, az[a], 0.8f, a <= 2 ? 1.0f : 0.0f};
            w[2 * a + 1] = new float[]{-1.38f, 0.8f, az[a], 0.8f, a <= 2 ? 1.0f : 0.0f};
        }
        return w;
    }

    /** 40 tube muzzles of the BM-21 launch package (4 rows x 10, muzzles at the FRONT end), pitch-frame coordinates, matching models/glb/grad.glb. */
    private static float[][] gradTubes() {
        float[][] t = new float[40][];
        for (int r = 0; r < 4; ++r) {
            for (int c = 0; c < 10; ++c) {
                t[r * 10 + c] = new float[]{-0.711f + 0.158f * (float)c, 0.10f + 0.165f * (float)r, 2.45f};
            }
        }
        return t;
    }

